func (q *Queries) ListPurchaseHistory(ctx context.Context, arg ListPurchaseHistoryParams) ([]ListPurchaseHistoryRow, error) {
	rows, err := q.db.Query(ctx, listPurchaseHistory,
		arg.PersonalOwnerID,
		arg.GroupID,
		arg.FromAt,
		arg.ToAt,
		arg.ListID,
		arg.PaidBy,
		arg.PurchasedBy,
		arg.CursorAt,
		arg.CursorID,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPurchaseHistoryRow{}
	for rows.Next() {
		var i ListPurchaseHistoryRow
		if err := rows.Scan(
			&i.ID,
			&i.ItemID,
			&i.ListID,
			&i.GroupID,
			&i.ItemName,
			&i.Quantity,
			&i.Unit,
			&i.ActualUnitPrice,
			&i.TotalAmount,
			&i.Currency,
			&i.RecordedBy,
			&i.PurchasedBy,
			&i.PaidBy,
			&i.PurchasedAt,
			&i.Notes,
			&i.ReversedBy,
			&i.ReversedAt,
			&i.ReversalReason,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RecordedByName,
			&i.PurchasedByName,
			&i.PaidByName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

